1	use std::sync::Arc;
2	
3	use dynamo_kv_hashing::compute_salt_hash;
4	use kvbm_logical::KvbmSequenceHashProvider;
5	use kvbm_logical::SequenceHash;
6	use kvbm_logical::blocks::ImmutableBlock;
7	use kvbm_logical::blocks::MutableBlock;
8	use kvbm_logical::events::EventsManager;
9	use kvbm_logical::events::KvCacheEvent;
10	use kvbm_logical::integrations::DecodeOutcome;
11	use kvbm_logical::integrations::SchedulableSequence;
12	use kvbm_logical::integrations::ScheduleError;
13	use kvbm_logical::manager::BlockManager;
14	use kvbm_logical::pools::BlockDuplicationPolicy;
15	use kvbm_logical::registry::BlockRegistry;
16	use tokio::sync::broadcast;
17	
18	use crate::view::KvView;
19	
20	/// Broadcast capacity for the opt-in KV-event feed. Generous: the scheduler
21	/// drains it every step, but a step can register/evict many blocks, and a
22	/// dropped event silently desyncs the router's prefix tree. Only allocated on
23	/// the [`BlockPool::with_events`] path.
24	const KV_EVENT_CHANNEL_CAPACITY: usize = 65_536;
25	
26	/// Logical KV block pool: a `BlockManager` plus the reserved padding block.
27	///
28	/// Owns no GPU memory — the physical layout (full-attention `KvBuffer`,
29	/// MLA dual ckv/kpe buffers, ...) lives with the consumer and is indexed
30	/// by the block IDs this pool hands out.
31	pub struct BlockPool {
32	    block_manager: BlockManager<()>,
33	    block_size: usize,
34	    padding_block_id: usize,
35	}
36	
37	impl BlockPool {
38	    pub fn new(block_size: usize, num_blocks: usize) -> anyhow::Result<Self> {
39	        Self::build(block_size, num_blocks, BlockRegistry::builder().build())
40	    }
41	
42	    /// Like [`new`](Self::new), but the pool also emits block store/remove
43	    /// events for an out-of-band cache-aware router, returned as a raw broadcast
44	    /// receiver to drain synchronously. The stream carries `Create` events too
45	    /// (the emission policy can't separate them) — the consumer ignores `Create`
46	    /// and sources richer store events from the seal site, and maps the lineage
47	    /// hash in each `Remove` back to the router's `sequence_hash`. OFF by
48	    /// default: plain single-machine serving uses [`new`](Self::new) and pays
49	    /// neither the per-block event attachment nor the channel.
50	    pub(crate) fn with_events(
51	        block_size: usize,
52	        num_blocks: usize,
53	    ) -> anyhow::Result<(Self, broadcast::Receiver<KvCacheEvent>)> {
54	        // Default emission policy is AllEventsPolicy (every block tracked).
55	        let events = Arc::new(
56	            EventsManager::builder()
57	                .channel_capacity(KV_EVENT_CHANNEL_CAPACITY)
58	                .build(),
59	        );
60	        let rx = events.subscribe_receiver();
61	        let registry = BlockRegistry::builder().event_manager(events).build();
62	        let pool = Self::build(block_size, num_blocks, registry)?;
63	        Ok((pool, rx))
64	    }
65	
66	    fn build(
67	        block_size: usize,
68	        num_blocks: usize,
69	        registry: BlockRegistry,
70	    ) -> anyhow::Result<Self> {
71	        anyhow::ensure!(num_blocks >= 2, "need at least 2 blocks (1 for padding)");
72	
73	        let block_manager = BlockManager::builder()
74	            .block_count(num_blocks)
75	            .block_size(block_size)
76	            .registry(registry)
77	            .duplication_policy(BlockDuplicationPolicy::Allow)
78	            .with_lru_backend()
79	            .build()
80	            .map_err(|e| anyhow::anyhow!("BlockManager build failed: {e}"))?;
81	
82	        // Reserve block 0 as CUDA Graph padding slot.
83	        let padding_blocks = block_manager
84	            .allocate_blocks(1)
85	            .ok_or_else(|| anyhow::anyhow!("failed to allocate padding block"))?;
86	        let padding_block_id = padding_blocks[0].block_id();
87	        let padding_complete = padding_blocks
88	            .into_iter()
89	            .next()
90	            .unwrap()
91	            .stage(SequenceHash::default(), block_size)
92	            .map_err(|e| anyhow::anyhow!("padding block stage failed: {e}"))?;
93	        // Register so it stays alive (ImmutableBlock RAII keeps it out of the
94	        // free pool), then leak — padding lives for the lifetime of the engine.
95	        std::mem::forget(block_manager.register_block(padding_complete));
96	
97	        Ok(Self {
98	            block_manager,
99	            block_size,
100	            padding_block_id,
101	        })
102	    }
103	
104	    pub fn block_size(&self) -> usize {
105	        self.block_size
106	    }
107	
108	    pub fn available_blocks(&self) -> usize {
109	        self.block_manager.available_blocks()
110	    }
111	
112	    pub fn total_blocks(&self) -> usize {
113	        self.block_manager.total_blocks()
114	    }
115	
116	    pub fn padding_block_id(&self) -> i32 {
117	        self.padding_block_id as i32
118	    }
119	
120	    /// Maximum blocks a single request can consume (total minus padding).
121	    pub fn max_request_blocks(&self) -> usize {
122	        self.block_manager.total_blocks().saturating_sub(1)
123	    }
124	
125	    /// Evict every cached-but-unused block from the GPU prefix cache (drain the
126	    /// inactive pool). In-use blocks are untouched. A cold-cache flush — and,
127	    /// for the offload path, the way to force a prefix out of HBM so a
128	    /// subsequent request must restore it from the CPU tier.
129	    pub fn evict_inactive(&self) {
130	        self.block_manager.evict_inactive();
131	    }
132	
133	    /// Return active prompt-prefix hashes without promoting inactive entries or
134	    /// keeping the matched blocks alive.
135	    pub fn active_prefix_hashes(
136	        &self,
137	        prompt_tokens: Vec<u32>,
138	        lora_name: Option<&str>,
139	    ) -> Vec<[u8; 16]> {
140	        let num_input = prompt_tokens.len();
141	        let request = self.new_request(prompt_tokens, 0, lora_name);
142	        let hashes = request.seq.inner().sequence().all_sequence_hashes();
143	        let cacheable = num_input.saturating_sub(1) / self.block_size;
144	        let active = self.block_manager.active_prefix_len(&hashes).min(cacheable);
145	        hashes[..active].iter().map(sequence_hash_bytes).collect()
146	    }
147	
148	    /// `lora_name` scopes the prefix cache: blocks registered under one
149	    /// adapter (or the base model, `None`) never match a request running
150	    /// under a different adapter — the name is folded into the block-hash
151	    /// chain as a salt, so K/V computed with different weights can't be
152	    /// silently reused.
153	    pub fn new_request(
154	        &self,
155	        prompt_tokens: Vec<u32>,
156	        max_output_tokens: usize,
157	        lora_name: Option<&str>,
158	    ) -> RequestKv {
159	        self.new_request_with_cache_salt(prompt_tokens, max_output_tokens, None, lora_name)
160	    }
161	
162	    /// Construct a request whose prefix-cache identity is additionally scoped
163	    /// by `cache_salt`. Use this when identical token blocks can produce
164	    /// different KV bytes because of state outside that block. `lora_name`
165	    /// remains a separate weight identity; callers must not overload it with
166	    /// request-local cache semantics.
167	    fn new_request_with_cache_salt(
168	        &self,
169	        prompt_tokens: Vec<u32>,
170	        max_output_tokens: usize,
171	        cache_salt: Option<&str>,
172	        lora_name: Option<&str>,
173	    ) -> RequestKv {
174	        let salt_hash = compute_salt_hash(cache_salt, lora_name)
175	            .expect("compute_salt_hash is infallible for string cache/lora identities");
176	        let seq = SchedulableSequence::new(
177	            prompt_tokens,
178	            max_output_tokens,
179	            self.block_size as u32,
180	            None,
181	            Some(salt_hash),
182	        );
183	        RequestKv {
184	            seq,
185	            emitted_blocks: 0,
186	        }
187	    }
188	
189	    // ── KV-offload prefetch (CPU-tier load before prefill) ─────────────
190	
191	    /// Resolve `prompt_tokens` against the GPU prefix cache *without* creating
192	    /// a request, returning a [`PrefixProbe`] that holds the GPU-hit prefix
193	    /// blocks alive so an async CPU-tier load can extend it. The connector
194	    /// queries the probe's [`PrefixProbe::cpu_query_hashes`] against the host
195	    /// tier, then [`reserve_loaded_blocks`](Self::reserve_loaded_blocks) +
196	    /// load + [`commit_loaded_blocks`](Self::commit_loaded_blocks).
197	    ///
198	    /// `lora_name` must match the request's adapter — it salts the block
199	    /// hashes, so probing under the wrong adapter would query unrelated keys.
200	    pub fn probe_prefix(&self, prompt_tokens: Vec<u32>, lora_name: Option<&str>) -> PrefixProbe {
201	        self.probe_prefix_with_cache_salt(prompt_tokens, None, lora_name)
202	    }
203	
204	    /// [`Self::probe_prefix`] with the same additional cache scope accepted by
205	    /// [`Self::new_request_with_cache_salt`]. The producer request and every
206	    /// restore probe must derive the identical salt.
207	    fn probe_prefix_with_cache_salt(
208	        &self,
209	        prompt_tokens: Vec<u32>,
210	        cache_salt: Option<&str>,
211	        lora_name: Option<&str>,
212	    ) -> PrefixProbe {
213	        let num_input = prompt_tokens.len();
214	        let rkv = self.new_request_with_cache_salt(prompt_tokens, 0, cache_salt, lora_name);
215	        let seq_hashes = rkv.seq.inner().sequence().all_sequence_hashes();
216	        // match_and_add_prefix leaves >=1 prompt token uncached, so a request
217	        // can reuse at most this many leading blocks — the CPU load must not
218	        // exceed it, or the trailing loaded block would never be re-matched.
219	        let cacheable = num_input.saturating_sub(1) / self.block_size;
220	        let gpu_guard = self.block_manager.match_blocks(&seq_hashes);
221	        let gpu_hit = gpu_guard.len();
222	        PrefixProbe {
223	            seq_hashes,
224	            gpu_hit,
225	            cacheable,
226	            block_size: self.block_size,
227	            held: gpu_guard,
228	        }
229	    }
230	
231	    /// Reserve `count` mutable blocks as the GPU destinations for a CPU→GPU
232	    /// load. Returns `None` under block pressure (the caller then skips the
233	    /// prefetch and prefills from scratch). The reservation's
234	    /// [`LoadReservation::page_ids`] feed the connector's load; on completion
235	    /// hand it to [`commit_loaded_blocks`](Self::commit_loaded_blocks).
236	    pub fn reserve_loaded_blocks(&self, count: usize) -> Option<LoadReservation> {
237	        let blocks = self.block_manager.allocate_blocks(count)?;
238	        Some(LoadReservation { blocks })
239	    }
240	
241	    /// Stage + register the freshly-loaded blocks under the probe's
242	    /// continuation hashes (`seq_hashes[gpu_hit .. gpu_hit + reserved]`) and
243	    /// fold them into the probe's held set, so a following
244	    /// `new_request().match_and_add_prefix()` reuses the full GPU+CPU prefix.
245	    ///
246	    /// The probe keeps holding every registered block until the request
247	    /// prefills, closing the eviction window between registration and re-match.
248	    pub fn commit_loaded_blocks(&self, probe: &mut PrefixProbe, reservation: LoadReservation) {
249	        let start = probe.gpu_hit;
250	        for (i, block) in reservation.blocks.into_iter().enumerate() {
251	            let hash = probe.seq_hashes[start + i];
252	            let complete = block
253	                .stage(hash, self.block_size)
254	                .expect("loaded block stage: block_size invariant violated");
255	            probe.held.push(self.block_manager.register_block(complete));
256	        }
257	    }
258	}
259	
260	/// A prompt's prefix resolved against the GPU cache, ready to drive a CPU-tier
261	/// prefetch. Holds every GPU-hit (and, after commit, CPU-loaded) block so they
262	/// can't be evicted while the load is in flight and before the request prefills.
263	pub struct PrefixProbe {
264	    /// Content hashes of every complete prompt block, in order (native form).
265	    seq_hashes: Vec<SequenceHash>,
266	    /// Length of the contiguous GPU-resident prefix.
267	    gpu_hit: usize,
268	    /// Reuse cap: blocks past this are never matched (the final chunk forwards).
269	    cacheable: usize,
270	    /// Tokens represented by one complete KV block.
271	    block_size: usize,
272	    /// Strong refs keeping matched/loaded blocks resident until prefill.
273	    held: Vec<ImmutableBlock<()>>,
274	}
275	
276	impl PrefixProbe {
277	    /// Blocks already resident in GPU HBM (the existing prefix-cache hit).
278	    pub fn gpu_hit_blocks(&self) -> usize {
279	        self.gpu_hit
280	    }
281	
282	    /// Total blocks this probe holds: the GPU-hit prefix plus any committed from
283	    /// a CPU-tier load. They are already out of the free pool and become the
284	    /// request's cached prefix at prefill, so admission credits them against the
285	    /// request's block need (avoiding a double-count against `available_blocks`).
286	    pub fn held_blocks(&self) -> usize {
287	        self.held.len()
288	    }
289	
290	    /// Complete prefix blocks eligible for request reuse.
291	    ///
292	    /// This is capped by the final-token rule even if a caller extended the
293	    /// probe with additional loaded blocks.
294	    pub fn reusable_blocks(&self) -> usize {
295	        self.held.len().min(self.cacheable)
296	    }
297	
298	    /// Returns the lineage hash identifying the complete reusable prefix ending
299	    /// at `boundary_tokens`.
300	    ///
301	    /// `boundary_tokens` is measured in tokens. For example,
302	    /// with a 16-token block size, `boundary_hash(32)` identifies the token
303	    /// prefix `[0, 32)`. The returned hash covers the full prefix lineage,
304	    /// rather than only the contents of the final block.
305	    ///
306	    /// Returns `None` when the boundary is zero, is not block-aligned, or
307	    /// exceeds the reusable prefix.
308	    pub fn boundary_hash(&self, boundary_tokens: usize) -> Option<[u8; 16]> {
309	        if boundary_tokens == 0 || !boundary_tokens.is_multiple_of(self.block_size) {
310	            return None;
311	        }
312	        let block_count = boundary_tokens / self.block_size;
313	        if block_count > self.reusable_blocks() {
314	            return None;
315	        }
316	        self.seq_hashes
317	            .get(block_count - 1)
318	            .map(sequence_hash_bytes)
319	    }
320	
321	    /// Content hashes to query the CPU tier with: the blocks past the GPU hit,
322	    /// capped at the reuse boundary. Empty when the GPU hit already covers
323	    /// every reusable block (nothing to load — prefill normally).
324	    pub fn cpu_query_hashes(&self) -> Vec<Vec<u8>> {
325	        if self.gpu_hit >= self.cacheable {
326	            return Vec::new();
327	        }
328	        self.seq_hashes[self.gpu_hit..self.cacheable]
329	            .iter()
330	            .map(|h| sequence_hash_bytes(h).to_vec())
331	            .collect()
332	    }
333	
334	    /// Number of blocks [`Self::cpu_query_hashes`] covers, without
335	    /// materializing the hash bytes. Callers substituting their own key
336	    /// scheme (vLLM-compat P/D) slice their chain to exactly this window.
337	    pub fn cpu_query_window(&self) -> usize {
338	        self.cacheable.saturating_sub(self.gpu_hit)
339	    }
340	}
341	
342	/// An opaque strong pin on one registered KV block. While held it keeps the
343	/// block in the active pool (out of the free/inactive pools), so the physical
344	/// slot cannot be reallocated. Used to hold a block stable across an in-flight
345	/// async offload save; cheap to clone/drop (one `Arc` bump). See
346	/// [`RequestKv::assigned_block_guards`].
347	///
348	/// The inner guard is never read — it exists purely for its `Drop`, which
349	/// releases the pin. Holding the value *is* the contract.
350	pub struct KvBlockGuard(#[allow(dead_code)] ImmutableBlock<()>);
351	
352	/// GPU destination blocks reserved for a CPU→GPU load, consumed by
353	/// [`BlockPool::commit_loaded_blocks`] once the DMA lands.
354	pub struct LoadReservation {
355	    blocks: Vec<MutableBlock<()>>,
356	}
357	
358	impl LoadReservation {
359	    /// Physical page ids the connector loads the leased CPU blocks into, in
360	    /// lease order (the i-th leased block lands in `page_ids()[i]`).
361	    pub fn page_ids(&self) -> Vec<i32> {
362	        self.blocks.iter().map(|b| b.block_id() as i32).collect()
363	    }
364	
365	    /// Number of reserved destination blocks.
366	    // `is_empty` was dead code (hawk sweep, #743); `len` stands alone.
367	    #[allow(clippy::len_without_is_empty)]
368	    pub fn len(&self) -> usize {
369	        self.blocks.len()
370	    }
371	}
372	
373	/// Per-request KV state wrapping `SchedulableSequence`.
374	///
375	/// Lifecycle: `schedule_prefill → prefill_view/pages → forward → apply_prefill`,
376	/// then either `schedule_decode → decode_view → forward → apply_decode` or
377	/// `schedule_speculative → speculative_view → forward → apply_speculative` in a
378	/// loop (`revert_schedule` undoes a reservation whose step failed).
379	pub struct RequestKv {
380	    seq: SchedulableSequence<()>,
381	    /// Cursor for [`Self::take_newly_registered_blocks`]: how many of this
382	    /// request's sequence blocks have already been surfaced as KV-router store
383	    /// events. Starts past the prefix-cache hit (those were stored by whoever
384	    /// first sealed them — this assumes GPU-resident reuse, i.e. KV offload off,
385	    /// which holds wherever the event feed is enabled). Untouched on the plain
386	    /// path where the feed is off.
387	    emitted_blocks: usize,
388	}
389	
390	impl RequestKv {
391	    // ── Prefix cache ───────────────────────────────────────────────────
392	
393	    /// Match the prompt's full blocks against registered blocks and skip
394	    /// their prefill. Returns the number of cached tokens; `kv_position()`
395	    /// advances by the same amount. Must be called on a fresh request,
396	    /// before the first `schedule_prefill`.
397	    ///
398	    /// Matching always leaves at least one prompt token uncached so the
399	    /// final prefill chunk can emit the first generated token.
400	    pub fn match_and_add_prefix(&mut self, pool: &BlockPool) -> anyhow::Result<usize> {
401	        self.match_and_add_prefix_up_to(pool, usize::MAX)
402	    }
403	
404	    /// Match and attach no more than `max_blocks` of the resident prefix.
405	    ///
406	    /// The underlying sequence still enforces the final-token cap. A caller
407	    /// can hold a [`PrefixProbe`] while invoking this method to ensure the
408	    /// selected blocks remain resident between joint-state lookup and attach.
409	    pub fn match_and_add_prefix_up_to(
410	        &mut self,
411	        pool: &BlockPool,
412	        max_blocks: usize,
413	    ) -> anyhow::Result<usize> {
414	        let blocks = self
415	            .seq
416	            .match_and_add_prefix_up_to(&pool.block_manager, max_blocks)
417	            .map_err(|e| anyhow::anyhow!("match_and_add_prefix_up_to: {e}"))?;
418	        // Prefix-hit blocks are already in the router's tree (whoever first
419	        // sealed them stored them, and a GPU hit means they were never evicted),
420	        // so the store-event cursor skips them.
421	        self.emitted_blocks = self.seq.assigned_blocks();
422	        Ok(blocks * self.seq.block_size())
423	    }
424	
425	    /// Returns the lineage hash identifying the registered prefix ending at
426	    /// `boundary_tokens`.
427	    ///
428	    /// `boundary_tokens` must be a non-zero multiple of the KV `block_size`,
429	    /// and be no more than the number of blocks already registered by this request;
430	    /// otherwise this method returns `None`.
431	    pub fn registered_boundary_hash(&self, boundary_tokens: usize) -> Option<[u8; 16]> {
432	        let block_size = self.seq.block_size();
433	        if boundary_tokens == 0 || !boundary_tokens.is_multiple_of(block_size) {
434	            return None;
435	        }
436	        let block_count = boundary_tokens / block_size;
437	        if block_count > self.seq.assigned_blocks() {
438	            return None;
439	        }
440	        self.seq
441	            .inner()
442	            .sequence()
443	            .all_sequence_hashes()
444	            .get(block_count - 1)
445	            .map(sequence_hash_bytes)
446	    }
