477	    /// Build an immutable `KvView` for prefill.
478	    ///
479	    /// `prompt_len` tokens will be appended starting at `kv_position()`.
480	    /// The view's seq_len = kv_position + prompt_len (post-advance state
481	    /// that FlashInfer attention metadata expects). The page row is exact
482	    /// (`step_page_indices`), never the raw block holdings — the raw list
483	    /// can carry an eagerly-allocated next block the kernel must not see.
484	    pub fn prefill_view(&self, prompt_len: usize) -> KvView {
485	        let target_seq_len = self.seq.kv_position() + prompt_len;
486	        KvView::new(
487	            self.step_page_indices(prompt_len),
488	            target_seq_len,
489	            self.seq.block_size(),
490	        )
491	    }
