505	    /// followed by draft candidates). The view covers the post-step KV extent;
506	    /// [`Self::apply_speculative`] later commits only the accepted prefix and
507	    /// releases excess draft capacity. Same exact page-row contract as
508	    /// [`Self::prefill_view`].
509	    pub fn speculative_view(&self, num_draft_tokens: usize) -> KvView {
510	        KvView::new(
511	            self.step_page_indices(num_draft_tokens),
512	            self.seq.kv_position() + num_draft_tokens,
513	            self.seq.block_size(),
514	        )
